PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?college coress-ont:hasDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?publicationType
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?college ?university ?city 
WHERE {
  ?college coress-ont:collegeOf ?university .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication (COALESCE(?title, "No title available")) AS ?publicationTitle
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasTitle ?title .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?department
ORDER BY DESC(?count)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author 
WHERE { 
    ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?department 
WHERE {
    ?department rdf:type coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate 
WHERE {
    ?publication a coresr-ont:Publication .
    ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX : <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
    ?author :advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department 
WHERE {
    ?agent coresr-ont:associatedWith ?department .
}

PREFIX : <http://example.org/core_scholar_rich/>

SELECT ?publication ?fieldOfStudy 
WHERE {
    ?publication :associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?collegeName ?cityName 
WHERE {
    ?college rdf:type coresr-ont:College ;
           rdfs:label ?collegeName ;
           coresr-ont:partOf ?university .

    ?university rdf:type coresr-ont:University ;
               coresr-ont:locatedAt ?location .

    ?location coresr-ont:atState ?state .

    ?state coresr-ont:inCity ?city .

    ?city rdfs:label ?cityName .
}
OPTIONAL {
    ?college coresr-ont:partOf ?university .
} 
OPTIONAL { 
    ?university coresr-ont:locatedAt ?location . 
}
OPTIONAL { 
    ?location coresr-ont:atState ?state .
}
OPTIONAL { 
    ?state coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?duration) AS ?avgDuration)
WHERE {
  ?publication a coresr-ont:Publication ;
    coresr-ont:hasPublicationType ?pubType ;
    coresr-ont:dateOfSubmission ?subDate ;
    coresr-ont:dateOfPublication ?pubDate .

  BIND(YEAR(?pubDate) - YEAR(?subDate) AS ?yearDiff)
  BIND(MONTH(?pubDate) - MONTH(?subDate) AS ?monthDiff)
  BIND(DAY(?pubDate) - DAY(?subDate) AS ?dayDiff)

  # Calculate total duration in days (simplified, actual calculation may require more precise handling)
  BIND((?yearDiff * 365) + (?monthDiff * 30) + ?dayDiff AS ?duration)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .

  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY ?missingFamilyNameCount DESC

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?hazard ?hazardLabel ?temporalScope ?spatialRelation ?geometry
WHERE {
  ?hazard rdf:type kwg-ont:Hazard .
  ?hazard rdfs:label ?hazardLabel .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?spatialRelation . }
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
}
ORDER BY ?hazardLabel

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?place ?name 
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
  OPTIONAL { ?place gnis:officialName ?name . }
  FILTER(!ISBLANK(?name))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?geographicalPlace ?healthConcernAttribute 
WHERE {
    ?geographicalPlace a kwg-ont:GeographicalPlace .
    ?geographicalPlace kwg-ont:healthConcernAttribute ?healthConcernAttribute .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?earthquake (COUNT(DISTINCT ?earthquake) AS ?count)
WHERE {
  {
    SELECT DISTINCT ?earthquake
    WHERE {
      ?obs a sosa:EarthquakeObservation ;
           sosa:hasFeatureOfInterest ?earthquake .
      ?earthquake rdfs:subClassOf* kwg-ont:Earthquake .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?earthquake ?property ?value ?type 
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  ?earthquake sosa:observedProperty ?property .
  ?property sosa:hasSimpleResult ?value .
  OPTIONAL { ?earthquake kwg-ont:type ?type . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?impactObservableProperty ?value ?hazardEvent WHERE {
  ?impactObservation sosa:hasFeatureOfInterest ?hazardEvent .
  ?impactObservation sosa:observedProperty ?impactObservableProperty .
  ?impactObservation sosa:hasSimpleResult ?value .

  FILTER EXISTS {
    ?impactObservableProperty rdfs:subClassOf kwg-ont:ImpactObservableProperty
  }

  ?hazardEvent rdfs:subClassOf kwg-ont:Hazard
}
GROUP BY ?hazardEvent ?impactObservableProperty ?value

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?impactDetail ?hazardTime ?impactTime 
WHERE {
  # Hurricane-specific hazard attributes related to a geographical place
  ?hazard a kwg-ont:NOAAHazardEvent ;
    sosa:observedProperty ?hazardAttribute ;
    kwg-ont:spatialRelation ?geographicalPlace ;
    kwg-ont:hasTemporalScope ?hazardTime .

  # Damage impact details and their temporal data
  ?impactObservation a kwg-ont:ImpactObservation ;
    sosa:hasFeatureOfInterest ?hazard ;
    sosa:observedProperty ?impactDetail ;
    kwg-ont:hasTemporalScope ?impactTime .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?damageDetail ?hazardEvent ?temporalExtent 
WHERE {
  _:b1 a kwg-ont:ImpactObservation ;
     sosa:hasSimpleResult ?damageDetail ;
     sosa:hasFeatureOfInterest ?hazardEvent .

  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
    kwg-ont:hasTemporalScope ?temporalExtent .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?hazardType ?name ?startDate ?endDate ?dollarDamage
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }

  # Example dollar damage property - can be expanded to other types if needed
  OPTIONAL { 
    ?hazard kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamage .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
