  OPTIONAL { ?place kwgl-ont:hasPopulation ?hasPopulation . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?hasNumberOfHouseHolds . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?attributeLabel (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  ?attribute rdf:type rdf:Property .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado")) .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
}
GROUP BY ?count

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?attributeLabel ?domain ?range
WHERE {
  ?attribute rdf:type rdf:Property .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:domain ?domain . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?hazardName
  ?startDate
  ?endDate
  ?damage
  ?deaths
  ?hazardType
  ?hazardTypeName
  ?spatialRelation
WHERE {
