  ?attribute rdf:type rdf:Property .

  FILTER (
    REGEX(STR(?attribute), "hurricane", "i") ||
    REGEX(STR(?attributeLabel), "hurricane", "i")
  )

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER NOT EXISTS {
    ?attribute <http://www.w3.org/2000/01/rdf-schema#isDefinedBy> [] 
      FILTER NOT CONTAINS(STR(?_), "kwgl-ont")
  }
}
ORDER BY ?attribute

