PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?hazardEvent ?hazardType ?attribute ?value
WHERE {
    ?place a kwgl-ont:Place .
    ?place kwgl-ont:impactedBy ?hazardEvent .
    ?hazardEvent a kwgl-ont:HazardEvent .
    ?hazardEvent kwgl-ont:hasHazardType ?hazardType .

    # Collect all storm-specific hazard attributes
    {
        SELECT DISTINCT ?attribute ?value
        WHERE {
            {
                ?hazardEvent kwgl-ont:hasName ?value .
                BIND(kwgl-ont:hasName AS ?attribute)
            }
            UNION
            {
                ?hazardEvent kwgl-ont:hasStartDate ?value .
                BIND(kwgl-ont:hasStartDate AS ?attribute)
            }
            UNION
            {
                ?hazardEvent kwgl-ont:hasEndDate ?value .
                BIND(kwgl-ont:hasEndDate AS ?attribute)
            }
            UNION
            {
                ?hazardEvent kwgl-ont:damageToCropsInDollars ?value .
                BIND(kwgl-ont:damageToCropsInDollars AS ?attribute)
            }
            UNION
            {
                ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?value .
                BIND(kwgl-ont:damageToInfrastructureInDollars AS ?attribute)
            }
            UNION
            {
                ?hazardEvent kwgl-ont:affectedAreaInAcres ?value .
                BIND(kwgl-ont:affectedAreaInAcres AS ?attribute)
            }
        }
    }

    # Collect all place attributes
    UNION
    {
        SELECT DISTINCT ?attribute ?value
        WHERE {
            {
                ?place kwgl-ont:hasName ?value .
                BIND(kwgl-ont:hasName AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?value .
                BIND(kwgl-ont:averageMonthlyTemperatureInCelsius AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?value .
                BIND(kwgl-ont:maximumMonthlyTemperatureInCelsius AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?value .
                BIND(kwgl-ont:minimumMonthlyTemperatureInCelsius AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?value .
                BIND(kwgl-ont:averageHeatingDegreeDaysPerMonth AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?value .
                BIND(kwgl-ont:averageCoolingDegreeDaysPerMonth AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value .
                BIND(kwgl-ont:dollarDamageOfFiresImpactingPlace AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value .
                BIND(kwgl-ont:dollarDamageOfFloodsImpactingPlace AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value .
                BIND(kwgl-ont:dollarDamageOfHurricanesImpactingPlace AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value .
                BIND(kwgl-ont:dollarDamageOfLandslidesImpactingPlace AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value .
                BIND(kwgl-ont:dollarDamageOfStormSurgesImpactingPlace AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value .
                BIND(kwgl-ont:dollarDamageOfTornadoesImpactingPlace AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:hasPopulation ?value .
                BIND(kwgl-ont:hasPopulation AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:percentBelowPovertyLine ?value .
                BIND(kwgl-ont:percentBelowPovertyLine AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:percentDiabetic ?value .
                BIND(kwgl-ont:percentDiabetic AS ?attribute)
            }
            UNION
            {
                ?place kwgl-ont:percentObese ?value .
                BIND(kwgl-ont:percentObese AS ?attribute)
            }
        }
    }
}

