PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?author 
WHERE {
    ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department 
WHERE {
    ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pub ?submissionDate 
WHERE {
    ?pub a coress-ont:Publication .
    ?pub coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city WHERE {
    ?university a coress-ont:University .
    ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisor 
WHERE {
    ?author a coress-ont:Author .
    ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?publicationType 
WHERE {
    ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department 
WHERE {
    ?agent a coress-ont:Agent .
    ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?fieldOfStudy 
WHERE {
    ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?pubTitle
WHERE {
    ?publication a coress-ont:Publication ;
        coress-ont:submittedBy ?author1, ?author2 ;
        coress-ont:hasTitle ?pubTitle .

    ?author1 coress-ont:worksInDepartment ?dept1 .
    ?author2 coress-ont:worksInDepartment ?dept2 .

    FILTER(?dept1 != ?dept2)
}
GROUP BY ?publication ?pubTitle

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationType (AVG(?duration) AS ?averageDuration)
WHERE {
    ?pub coress-ont:dateOfSubmission ?submissionDate .
    ?pub coress-ont:dateOfPublication ?publicationDate .
    ?pub coress-ont:hasPublicationType ?publicationType .

    BIND(YEAR(?publicationDate) - YEAR(?submissionDate) AS ?duration)

    FILTER NOT EXISTS {
        ?pub coress-ont:dateOfSubmission [] .
        FILTER NOT EXISTS { ?pub coress-ont:dateOfPublication [] }
    }
}
GROUP BY ?publicationType
ORDER BY DESC(?averageDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(*) AS ?count)
