PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?fieldOfStudy 
WHERE {
    ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?pub ?title
WHERE {
    ?pub a coress-ont:Publication ;
        coress-ont:hasTitle ?title ;
        coress-ont:submittedBy ?author1 .
    ?author1 coress-ont:worksInDepartment ?dept1 .

    {
        SELECT ?pub (COUNT(DISTINCT ?dept) AS ?deptCount)
        WHERE {
            ?pub a coress-ont:Publication ;
                coress-ont:submittedBy ?author2 .
            ?author2 coress-ont:worksInDepartment ?dept .
        }
        GROUP BY ?pub
        HAVING (COUNT(DISTINCT ?dept) >= 2)
    }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?authorFirstName WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:hasFirstName ?authorFirstName .
  ?author coress-ont:advisedBy ?advisor .
  ?publication coress-ont:submittedBy ?author .
  ?publication coress-ont:associatedFieldOfStudy ?field .

  FILTER NOT EXISTS {
    ?otherPublication coress-ont:submittedBy ?author .
    ?otherPublication coress-ont:associatedFieldOfStudy ?sameField .
    FILTER (?field = ?sameField)
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?count)
WHERE {
    ?agent a coress-ont:Agent .
    ?agent coress-ont:worksInDepartment ?department .
    FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName [] }
}
GROUP BY ?department
ORDER BY DESC(?count)

