PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hazard ?hazardLabel ?detail
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?hazardLabel . }
  OPTIONAL { ?hazard skos:description ?description . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time . }
  BIND(CONCAT(
    STRBEFORE(STRAFTER(STR(?hazard), "http://stko-kwg.geog.ucsb.edu/lod/ontology/"), "_"),
    "	",
    COALESCE(?hazardLabel, "No label"),
    "	",
    COALESCE(?description, "No description"),
    "	",
    COALESCE(?time, "No time")
  ) AS ?detail)
}
ORDER BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
