PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  {
    ?place rdfs:subClassOf* kwg-ont:AdministrativeRegion .
  } UNION {
    ?place rdfs:subClassOf* kwg-ont:S2Cell .
  } UNION {
    ?place rdfs:subClassOf* kwg-ont:ZipCodeArea .
  }
  OPTIONAL { ?place rdfs:label ?name . }
  BIND(COALESCE(?name, ?place)) AS ?name
}
ORDER BY ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?attribute ?value
WHERE {
    ?hazard a kwg-ont:Hazard .
    FILTER(REGEX(STR(?hazard), "Storm")) .

    {
        SELECT DISTINCT ?hazard (rdf:type AS attribute) (rdfs:label AS value)
        WHERE { ?hazard rdf:type ?type . ?hazard rdfs:label ?value . }
    } UNION {
        ?hazard kwg-ont:magnitudeObservableProperty ?mobs .
        ?mobs sosa:hasSimpleResult ?value .
        BIND("magnitude" AS ?attribute) .
    } UNION {
        ?hazard kwg-ont:impactObservableProperty ?iobs .
        ?iobs sosa:hasSimpleResult ?value .
        BIND("impact" AS ?attribute) .
    } UNION {
        ?hazard sosa:phenomenonTime ?time .
        BIND("phenomenonTime" AS ?attribute) .
        BIND(str(?time) AS ?value) .
    } UNION {
        ?hazard geo:hasGeometry ?geometry .
        BIND("geometry" AS ?attribute) .
        BIND(str(?geometry) AS ?value) .
    } UNION {
        ?hazard sosa:hasSimpleResult ?value .
        BIND("simpleResult" AS ?attribute) .
    }
}
ORDER BY ?hazard ?attribute
LIMIT 1000

