  OPTIONAL { ?earthquake kwg-ont:locationSource ?locationSource . }
  OPTIONAL { ?earthquake kwg-ont:gap ?gap . }
  OPTIONAL { ?earthquake kwg-ont:horizontalError ?horizontalError . }
  OPTIONAL { ?earthquake kwg-ont:rms ?rms . }
  OPTIONAL { ?earthquake kwg-ont:nst ?nst . }
