  OPTIONAL { ?earthquake kwg-ont:magSource ?magSource . }
  OPTIONAL { ?earthquake kwg-ont:magType ?magType . }
  OPTIONAL { ?earthquake kwg-ont:dmin ?dmin . }
  OPTIONAL { ?earthquake kwg-ont:status ?status . }
  OPTIONAL { ?earthquake kwg-ont:type ?type . }
