PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactObservationCollection ?property ?value
WHERE {
  ?impactObservationCollection sosa:hasFeatureOfInterest ?hazardEvent .
  FILTER(sosa:isFeatureOfInterestOf(?hazardEvent, ?impactObservationCollection))

  OPTIONAL { 
    ?hazardEvent kwg-ont:spatialRelation ?relatedRegion . 
  }

  ?impactObservationCollection sosa:hasMember ?impactObservation .
  ?impactObservation ?property ?value .
}
ORDER BY ?hazardEvent ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?damage_observation ?property ?value ?hazard_event ?time
WHERE {
    ?damage_observation a kwg-ont:ImpactObservation .

    ?damage_observation sosa:observedProperty ?property .
    ?property rdfs:subClassOf kwg-ont:ImpactObservableProperty .

    ?damage_observation sosa:hasFeatureOfInterest ?hazard_event .
    ?hazard_event rdfs:subClassOf* kwg-ont:Hazard .

    OPTIONAL { 
        ?damage_observation sosa:phenomenonTime ?time . 
    }

    OPTIONAL {
        ?damage_observation sosa:hasSimpleResult ?value .
    }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardAttribute ?spatialRelation ?impactDetail ?temporalData
WHERE {
  ?hurricane rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  ?hurricane a kwg-ont:NOAAHurricane .

  OPTIONAL { ?hurricane kwg-ont:hazardAttribute ?hazardAttribute . }

  OPTIONAL { 
    ?hurricane kwg-ont:spatialRelation ?geographicalPlace .
    ?geographicalPlace rdfs:subClassOf* geo:SpatialObject .
    ?geographicalPlace (geo:hasGeometry|kwg-ont:hasGeometry) ?spatialRelation .
  }

  OPTIONAL {
    ?hurricane obsrvd:relatedImpact ?impactObservation .
    ?impactObservation sosa:observedProperty ?impactDetail .
  }

  OPTIONAL {
    ?hurricane kwg-ont:hasTemporalScope|kwg-ont:temporalScope|sosa:phenomenonTime ?timeEntity .
    ?timeEntity a time:Instant|time:Interval|time:Duration .
    ?timeEntity rdfs:label ?temporalData .
  }
}
ORDER BY ?hurricane ?hazardAttribute

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?damageDetail ?location ?time
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:NOAATornado .

  OPTIONAL { 
    ?hazard sosa:hasFeatureOfInterest ?location .
    ?location a geo:Feature .
  }

  OPTIONAL { 
    ?hazard kwg-ont:spatialRelation ?spatialRegion .
    ?spatialRegion rdfs:subClassOf* kwg-ont:AdministrativeRegion .
  }

  OPTIONAL {
    ?impactObservation sosa:hasFeatureOfInterest ?hazard .
    ?impactObservation sosa:observedProperty [
      a (kwgr:impactObservableProperty.damageCrop, 
         kwgr:impactObservableProperty.damageProperty,
         kwgr:impactObservableProperty.deathDirect,
         kwgr:impactObservableProperty.deathIndirect,
         kwgr:impactObservableProperty.injuryDirect,
         kwgr:impactObservableProperty.injuryIndirect) ;
    ] .
    ?damageDetail = strafter(str(?impactObservation), "#") .
  }

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?time .
    ?time a (time:Instant, time:Interval) .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
