PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?hazardLabel ?detail ?time
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?hazardLabel . }
  OPTIONAL { 
    ?hazard ?property ?value .
    BIND(CONCAT(STRAFTER(STR(?property), '#'), ': ', STR(?value)) AS ?detail) 
  }
  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?time .
    FILTER(REGEX(STR(?time), "http://www.w3.org/2006/time#"))
  }
}
ORDER BY ?hazardLabel ?detail

