PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hurricane ?magnitudeAttr ?spatialRel ?geoArea ?impactDetail ?temporal 
WHERE {
  ?hurricane a kwg-ont:NOAAHazardEvent ;
    a kwg-ont:NOAAHurricane ;
    sosa:hasFeatureOfInterest ?feature ;
    sosa:observedProperty ?magnitudeProp ;
    kwg-ont:spatialRelation ?geoArea ;
    sosa:hasResult ?impactObs ;
    OPTIONAL { 
      ?hurricane kwg-ont:hasTemporalScope ?temporal .
    }.

  ?magnitudeProp a kwg-ont:MagnitudeObservableProperty ;
    sosa:observedProperty ?magnitudeAttr .

  ?impactObs a kwg-ont:ImpactObservation ;
    sosa:observedProperty ?impactDetail .

  FILTER NOT EXISTS {
    ?hurricane a ?otherClass .
    ?otherClass rdfs:subClassOf kwg-ont:Hazard .
    FILTER (?otherClass != kwg-ont:NOAAHazardEvent)
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
    a ?stormType ;
    sosa:hasFeatureOfInterest ?location ;
    sosa:phenomenonTime ?time .

  FILTER (EXISTS {
    ?stormType rdfs:subClassOf* kwg-ont:NOAATornado .
  }) 

  FILTER NOT EXISTS {
    ?hazardEvent a kwg-ont:DroughtZone .
  }

  ?impactObservationCollection sosa:hasMember ?impactObservation ;
    sosa:phenomenonTime ?time ;
    sosa:observedProperty ?damageProperty .

  ?damageProperty rdfs:subClassOf* kwg-ont:ImpactObservableProperty .

  BINDING (?damageDetail AS ?damageProperty)
}

