  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?dollarDamageOfTornadoesImpactingPlace2018 . }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2019 ?dollarDamageOfStormSurgesImpactingPlace2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollarDamageOfHurricanesImpactingPlace2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?dollarDamageOfTornadoesImpactingPlace2019 . }

