PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?hurricaneAttribute ?geoProperty ?impactDetail ?temporalData
WHERE {
  ?hurricane rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  ?hurricane rdfs:label ?hurricaneAttribute .

  OPTIONAL { 
    ?hurricane geo:hasGeometry ?geometry .
    ?hurricane geo:hasDefaultGeometry ?defaultGeometry .
    BIND(CONCAT('Geometry: ', STR(?geometry), '
Default Geometry: ', STR(?defaultGeometry)) AS ?geoProperty)
  }

  OPTIONAL {
    ?hurricane :impactObservableProperty ?impact .
    ?impact rdfs:label ?impactDetail .
  }

  OPTIONAL {
    ?hurricane sosa:phenomenonTime|kwg-ont:hasTemporalScope ?time .
    BIND(CONCAT('Time: ', STR(?time)) AS ?temporalData)
  }
}
ORDER BY ?hurricaneAttribute ?geoProperty ?impactDetail ?temporalData

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardEvent ?hazardType ?impactDetail ?temporalExtent
WHERE {
  ?hazardEvent rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazardEvent rdfs:subClassOf ?hazardType . }
  OPTIONAL { 
    ?hazardEvent ?impactProperty ?impactValue .
    FILTER(?impactProperty = kwg-ont:damageCrop || ?impactProperty = kwg-ont:damageProperty)
    BIND(CONCAT(str(?impactProperty), ": ", str(?impactValue)) AS ?impactDetail)
  }
  OPTIONAL { 
    ?hazardEvent kwg-ont:hasTemporalScope ?temporalEntity .
    ?temporalEntity time:hasBeginning ?beginTime .
    ?temporalEntity time:hasEnd ?endTime .
    BIND(CONCAT("Start: ", str(?beginTime), "; End: ", str(?endTime)) AS ?temporalExtent)
  }
}
ORDER BY ?hazardEvent ?impactDetail

PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardType ?hazardName ?detail ?startTime ?endTime
WHERE {
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazardType rdfs:label ?hazardName . }
  OPTIONAL { 
    ?hazardType time:hasTemporalScope ?temporalEntity .
    ?temporalEntity a time:Instant ;
      time:inXSDDateTime ?startTime .
    ?temporalEntity time:end ?endTime .
  }
  OPTIONAL { 
    ?hazardType rdfs:label ?detail .
    ?hazardType skos:definition ?detail .
  }
  OPTIONAL { 
    ?hazardType ?detailPredicate ?detailValue .
    BIND(REPLACE(STR(?detailPredicate), "http://", "") AS ?detail )
    BIND(CONCAT(" (", STR(?detailValue), ")") AS ?detailValue)
  }
}
ORDER BY ?hazardType ?detail

