SELECT DISTINCT ?tornadoHazard ?label ?definition ?attribute ?value
WHERE {
  ?tornadoHazard rdfs:subClassOf kwg-ont:NOAATornado .

  OPTIONAL { 
    ?tornadoHazard rdfs:label ?label . 
    FILTER(langMatches(lang(?label), 'en')) 
  }

  OPTIONAL { 
    ?tornadoHazard skos:definition ?definition . 
    FILTER(langMatches(lang(?definition), 'en')) 
  }

  OPTIONAL { 
    ?attribute a owl:ObjectProperty, owl:DatatypeProperty . 
    ?tornadoHazard ?attribute ?value . 
  }

  {
    SELECT COUNT(*) AS ?count
    WHERE {
      ?tornadoHazard rdfs:subClassOf kwg-ont:NOAATornado .
      ?tornadoHazard ?attr ?val .
    }
  }
}

