PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?hazardType ?impactProperty ?impactValue ?vulnerability ?magnitude 
WHERE {
  ?hazardEvent a kwg-ont:Hazard .
  OPTIONAL { ?hazardEvent rdfs:subClassOf ?hazardType . }

 OPTIONAL {
    ?hazardEvent sosa:hasFeatureOfInterest ?observationCollection .
    ?observationCollection sosa:phenomenonTime ?temporalEntity .
    ?observationCollection sosa:hasMember ?impactObservation .
    ?impactObservation sosa:observedProperty ?impactProperty .
    ?impactObservation ?impactProperty ?impactValue .
  }

  OPTIONAL {
    ?hazardEvent sosa:hasFeatureOfInterest ?vulnerabilityCollection .
    ?vulnerabilityCollection sosa:phenomenonTime ?temporalEntity .
    ?vulnerabilityCollection sosa:hasMember ?vulnerabilityObservation .
    ?vulnerabilityObservation sosa:observedProperty ?vulnerability .
  }

  OPTIONAL {
    ?hazardEvent sosa:hasFeatureOfInterest ?magnitudeCollection .
    ?magnitudeCollection sosa:phenomenonTime ?temporalEntity .
    ?magnitudeCollection sosa:hasMember ?magnitudeObservation .
    ?magnitudeObservation sosa:observedProperty ?magnitude .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hurricane ?name ?disasterID ?category ?windSpeed ?magnitude 
       ?impactDetails ?cropDamage ?propertyDamage ?death ?injury 
       ?temporalScope
WHERE {
  ?hurricane rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  ?hurricane a kwg-ont:NOAAHurricane .

  OPTIONAL { ?hurricane kwg-ont:hasName ?name . }
  OPTIONAL { ?hurricane kwg-ont:noaaDisasterID ?disasterID . }
  OPTIONAL { ?hurricane kwg-ont:magnitudeObservableProperty.estimateSustainedWidth ?magnitude . }
  OPTIONAL { 
    ?hurricane kwg-ont:spatialRelation ?geographicalPlace .
    ?geographicalPlace rdfs:subClassOf* kwg-ont:AdministrativeRegion_3 .
  }

  OPTIONAL {
    ?hurricane kwg-ont:hasMagnitudeObservableProperty ?magnitudeProp .
    ?magnitudeProp sosa:hasValue ?magValue .
    ?magValue sosa:observedProperty ?magType .
    ?magType rdfs:label ?magnitude .
  }

  OPTIONAL {
    ?hurricaneImpact sosa:hasFeatureOfInterest ?hurricane .
    ?hurricaneImpact a kwg-ont:ImpactObservationCollection .
    ?hurricaneImpact sosa:phenomenonTime ?temporalScope .
    ?hurricaneImpact sosa:hasMember ?impactObs .
    ?impactObs sosa:observedProperty ?impactProp .
    ?impactProp rdfs:label ?impactDetails .

    OPTIONAL { 
      ?impactObs kwg-ont:impactObservableProperty.damageCrop ?cropDamage . 
      ?impactObs kwg-ont:impactObservableProperty.damageProperty ?propertyDamage . 
      ?impactObs kwg-ont:impactObservableProperty.deathDirect ?death .
      ?impactObs kwg-ont:impactObservableProperty.injuryDirect ?injury .
    }
  }

  OPTIONAL {
    ?hurricaneMagnitude sosa:hasFeatureOfInterest ?hurricane .
    ?hurricaneMagnitude a kwg-ont:MagnitudeObservationCollection .
    ?hurricaneMagnitude sosa:phenomenonTime ?temporalScope .
    ?hurricaneMagnitude sosa:hasMember ?magObs .
    ?magObs sosa:observedProperty ?catProp .
    ?catProp rdfs:label ?category .
    ?magObs kwg-ont:magnitudeObservableProperty.measuredSustainedWind ?windSpeed .
  }
}
ORDER BY ?hurricane

