SELECT DISTINCT ?hurricaneEvent ?hazardAttribute ?spatialRelation ?impactDetail ?temporalData 
WHERE {
    ?hurricaneEvent a kwg-ont:NOAAHazardEvent ;
        a kwg-ont:NOAAHurricane ;
        sosa:hasFeatureOfInterest ?geographicalPlace ;
        sosa:observedProperty ?hazardAttribute ;
        kwg-ont:spatialRelation ?spatialEntity ;
        kwg-ont:hasTemporalScope ?temporalScope .

    ?hurricaneEvent 
        sosa:hasResult [
            sosa:hasObservation [
                sosa:observedProperty ?impactDetail
            ]
        ].

    FILTER EXISTS {
        ?hurricaneEvent a kwg-ont:NOAAHazardEvent ;
            sosa:hasFeatureOfInterest ?geographicalPlace ;
            kwg-ont:spatialRelation ?spatialEntity ;
            kwg-ont:hasTemporalScope ?temporalData .
