PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?hazardAttribute
  ?attributeValue
  ?place
  ?stormHazardType
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  ?hazardEvent kwgl-ont:hasImpacted ?place .

  ?hazardEvent kwgl-ont:hasHazardType ?stormHazardType .
  FILTER(
    ?stormHazardType = kwglr:stormSurgeTide ||
    ?stormHazardType = kwglr:highWind ||
    ?stormHazardType = kwglr:heavyRain ||
    ?stormHazardType = kwglr:hurricane ||
    ?stormHazardType = kwglr:tornado ||
    ?stormHazardType = kwglr:thunderstormWind ||
    ?stormHazardType = kwglr:strongWind ||
    ?stormHazardType = kwglr:marineHighWind ||
    ?stormHazardType = kwglr:marineStrongWind ||
    ?stormHazardType = kwglr:marineThunderstormWind
  )

  OPTIONAL {
    ?hazardEvent kwgl-ont:affectedAreaInAcres ?attributeValue .
    BIND(kwgl-ont:affectedAreaInAcres AS ?hazardAttribute)
  }

  OPTIONAL {
    ?hazardEvent kwgl-ont:damageToCropsInDollars ?attributeValue .
    BIND(kwgl-ont:damageToCropsInDollars AS ?hazardAttribute)
  }

  OPTIONAL {
    ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?attributeValue .
    BIND(kwgl-ont:damageToInfrastructureInDollars AS ?hazardAttribute)
  }

  OPTIONAL {
    ?hazardEvent kwgl-ont:hasStartDate ?attributeValue .
    BIND(kwgl-ont:hasStartDate AS ?hazardAttribute)
  }

  OPTIONAL {
    ?hazardEvent kwgl-ont:hasEndDate ?attributeValue .
    BIND(kwgl-ont:hasEndDate AS ?hazardAttribute)
  }

  OPTIONAL {
    ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?attributeValue .
    BIND(kwgl-ont:averageMonthlyTemperatureInCelsius AS ?hazardAttribute)
  }

  OPTIONAL {
    ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?attributeValue .
    BIND(kwgl-ont:maximumMonthlyTemperatureInCelsius AS ?hazardAttribute)
  }

  OPTIONAL {
    ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?attributeValue .
    BIND(kwgl-ont:minimumMonthlyTemperatureInCelsius AS ?hazardAttribute)
  }
}
ORDER BY ?hazardEvent ?hazardAttribute

