        terms:atState ?state ;
        rdfs:label ?uniLabel .

    ?college coress-ont:collegeOf ?uni ;
                coress-ont:hasDepartment ?dept .

    ?dept coress-ont:departmentOf ?college ;
            coress-ont:hasAgent ?agent .

    ?agent coress-ont:worksInDepartment ?dept ;
              coress-ont:performsRole ?role .

