PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazardType ?label
WHERE {
  ?hazardType rdf:type kwgl-ont:HazardType ;
              rdfs:label ?label .

  FILTER(CONTAINS(LCASE(?label), "earthquake"))
}
ORDER BY ?label

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT 
  ?attribute
  ?attrLabel
  (COUNT(*) AS ?count)
WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamage2021 .
    BIND("dollarDamageOfTornadoesImpactingPlace" AS ?attribute)
    BIND("Dollar damage of tornadoes impacting place" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?dollarDamage2018 .
    BIND("dollarDamageOfTornadoesImpactingPlace2018" AS ?attribute)
    BIND("Dollar damage of tornadoes impacting place-2018" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?dollarDamage2019 .
    BIND("dollarDamageOfTornadoesImpactingPlace2019" AS ?attribute)
    BIND("Dollar damage of tornadoes impacting place-2019" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?dollarDamage2020 .
    BIND("dollarDamageOfTornadoesImpactingPlace2020" AS ?attribute)
    BIND("Dollar damage of tornadoes impacting place-2020" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?dollarDamage2021 .
    BIND("dollarDamageOfTornadoesImpactingPlace2021" AS ?attribute)
    BIND("Dollar damage of tornadoes impacting place-2021" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?dollarDamage2022 .
    BIND("dollarDamageOfTornadoesImpactingPlace2022" AS ?attribute)
    BIND("Dollar damage of tornadoes impacting place-2022" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:numberOfTornadoesImpactingPlace ?numTornadoes .
    BIND("numberOfTornadoesImpactingPlace" AS ?attribute)
    BIND("Number of tornadoes impacting place" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2018 ?numTornadoes2018 .
    BIND("numberOfTornadoesImpactingPlace2018" AS ?attribute)
    BIND("Number of tornadoes impacting place-2018" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2019 ?numTornadoes2019 .
    BIND("numberOfTornadoesImpactingPlace2019" AS ?attribute)
    BIND("Number of tornadoes impacting place-2019" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2020 ?numTornadoes2020 .
    BIND("numberOfTornadoesImpactingPlace2020" AS ?attribute)
    BIND("Number of tornadoes impacting place-2020" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2021 ?numTornadoes2021 .
    BIND("numberOfTornadoesImpactingPlace2021" AS ?attribute)
    BIND("Number of tornadoes impacting place-2021" AS ?attrLabel)
  }

  OPTIONAL { 
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2022 ?numTornadoes2022 .
    BIND("numberOfTornadoesImpactingPlace2022" AS ?attribute)
    BIND("Number of tornadoes impacting place-2022" AS ?attrLabel)
  }
}
GROUP BY ?attribute ?attrLabel
ORDER BY ?attrLabel

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?domain
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain ?domain . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(?attributeLabel), "storm")
  )
}
ORDER BY ?attribute

