PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardAttribute
  ?hazardAttrLabel
  ?damageToCrops
  ?damageToInfrastructure
  ?hurricaneDamage2018
  ?hurricaneDamage2019
  ?hurricaneDamage2020
  ?hurricaneDamage2021
  ?hurricaneDamage2022
  ?numHurricanes2018
  ?numHurricanes2019
  ?numHurricanes2020
  ?numHurricanes2021
  ?numHurricanes2022
  ?startDate
  ?endDate

WHERE {
  ?hazardAttribute rdf:type owl:DatatypeProperty ;
    rdfs:domain [
      rdf:type owl:Class ;
      owl:unionOf ( kwgl-ont:HazardEvent kwgl-ont:Place )
    ] ;
    rdfs:label ?hazardAttrLabel .

  OPTIONAL { ?hazardAttribute kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage . }
  OPTIONAL { ?hazardAttribute kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?hurricaneDamage2018 . }
  OPTIONAL { ?hazardAttribute kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?hurricaneDamage2019 . }
  OPTIONAL { ?hazardAttribute kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?hurricaneDamage2020 . }
  OPTIONAL { ?hazardAttribute kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?hurricaneDamage2021 . }
  OPTIONAL { ?hazardAttribute kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?hurricaneDamage2022 . }

  OPTIONAL {
    ?event a kwgl-ont:Hurricane ;
      kwgl-ont:impactedBy ?place ;
      kwgl-ont:hasStartDate ?startDate ;
      kwgl-ont:hasEndDate ?endDate .
  }

  OPTIONAL { ?hazardAttribute kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardAttribute kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }

  OPTIONAL {
    ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numHurricanes ;
      kwgl-ont:numberOfHurricanesImpactingPlace2018 ?numHurricanes2018 ;
      kwgl-ont:numberOfHurricanesImpactingPlace2019 ?numHurricanes2019 ;
      kwgl-ont:numberOfHurricanesImpactingPlace2020 ?numHurricanes2020 ;
      kwgl-ont:numberOfHurricanesImpactingPlace2021 ?numHurricanes2021 ;
      kwgl-ont:numberOfHurricanesImpactingPlace2022 ?numHurricanes2022 .
  }
}

ORDER BY ?hazardAttribute

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent
       ?hasImpacted 
       ?dollarDamage 
       ?startDate 
       ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado .

  ?hazardEvent kwgl-ont:hasImpacted ?hasImpacted .

  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?dollarDamage2018 . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?dollarDamage2019 . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?dollarDamage2020 . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?dollarDamage2021 . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?dollarDamage2022 . }

  FILTER (exists {
    [
      rdf:type kwgl-ont:HazardEvent ;
      kwgl-ont:hasStartDate ?startDate ;
      kwgl-ont:hasEndDate ?endDate ;
    ]
    FILTER (xsd:date(?startDate) >= "2018-01-01"^^xsd:date &&
            xsd:date(?endDate) <= "2022-12-31"^^xsd:date)
  })
}
ORDER BY ?hazardEvent

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author coresr-ont:submits ?publication .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?type
WHERE {
  ?publication coresr-ont:hasPublicationType ?pubType .
  ?pubType coresr-ont:typeAsString ?type .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  {
    SELECT ?publication
    WHERE {
      ?publication coresr-ont:contributedTo|coresr-ont:submittedBy ?agent .
      ?agent coresr-ont:associatedWith ?department .
    }
    GROUP BY ?publication
    HAVING (COUNT(DISTINCT ?department) > 1)
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department ?count
WHERE {
  {
    SELECT ?dept (COUNT(DISTINCT ?agent) AS ?count)
    WHERE {
      ?agent a coresr-ont:Agent .
      ?agent coresr-ont:associatedWith ?dept .
      FILTER NOT EXISTS { ?agent coresr-ont:FamilyName ?name . }
    }
    GROUP BY ?dept
  }
  ?department = ?dept .
}
ORDER BY DESC(?count)

PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xml: <http://www.w3.org/XML/1998/namespace>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX terms: <http://purl.org/dc/terms/>

SELECT ?hazard ?name ?deaths ?cropDamage ?infrastructureDamage ?affectedArea ?startDate ?endDate
WHERE {
    ?hazard rdf:type owl:Thing .
    ?hazard rdfs:subClassOf* :HazardEvent .

    OPTIONAL { ?hazard :hasName ?name . }
    OPTIONAL { ?hazard :numberOfDeaths ?deaths . }
    OPTIONAL { ?hazard :damageToCropsInDollars ?cropDamage . }
    OPTIONAL { ?hazard :damageToInfrastructureInDollars ?infrastructureDamage . }
    OPTIONAL { ?hazard :affectedAreaInAcres ?affectedArea . }
    OPTIONAL { ?hazard :hasStartDate ?startDate . }
    OPTIONAL { ?hazard :hasEndDate ?endDate . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name 
WHERE {
    ?place a kwgl-ont:Place ;
           kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?place ?population ?povertyLine ?diabetic ?obese 
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese . }
  FILTER (EXISTS { ?place kwgl-ont:hasPopulation ?_population } || 
          EXISTS { ?place kwgl-ont:percentBelowPovertyLine ?_povertyLine } || 
          EXISTS { ?place kwgl-ont:percentDiabetic ?_diabetic } || 
          EXISTS { ?place kwgl-ont:percentObese ?_obese })
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place 
       ?hasPopulation 
       ?hasNumberOfHouseHolds 
       ?percentBelowPovertyLine 
       ?percentDiabetic 
       ?percentObese
WHERE {
    ?place rdf:type kwgl-ont:Place ;
          kwgl-ont:hasPopulation ?hasPopulation ;
          kwgl-ont:hasNumberOfHouseHolds ?hasNumberOfHouseHolds ;
          kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine ;
          kwgl-ont:percentDiabetic ?percentDiabetic ;
          kwgl-ont:percentObese ?percentObese .

    FILTER(isLiteral(?hasPopulation) && isLiteral(?hasNumberOfHouseHolds) && 
           isLiteral(?percentBelowPovertyLine) && isLiteral(?percentDiabetic) && 
           isLiteral(?percentObese))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName COUNT(*) AS ?count
WHERE {
    ?hazard a kwgl-ont:HazardType ;
           rdfs:label ?hazardName .
