PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?hazardEvent ?impactType ?injuryCount ?deathCount ?property ?value
WHERE {
  ?impactCollection a kwg-ont:ImpactObservationCollection .
  ?impactCollection sosa:hasFeatureOfInterest ?hazardEvent .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .

  OPTIONAL { 
    ?impactCollection sosa:hasMember ?impactObs .
    ?impactObs sosa:observedProperty ?impactType .
    ?impactType rdfs:label ?impactLabel .
    FILTER (regex(str(?impactType), "damage"))
  }

  OPTIONAL {
    ?hazardEvent kwg-ont:deathDirect ?deathCount .
    ?hazardEvent kwg-ont:injuryDirect ?injuryCount .
  }

  OPTIONAL { 
    ?hazardEvent ?property ?value .
    FILTER NOT EXISTS { ?property rdf:type owl:NamedIndividual }
  }
}
ORDER BY ?hazardEvent

