    sosa:observedProperty [
      a kwg-ont:ImpactObservableProperty ;
      kwgr:impactObservableProperty.damageCrop ?damageCrop ;
      kwgr:impactObservableProperty.damageProperty ?damageProperty ;
      kwgr:impactObservableProperty.deathDirect ?deathDirect ;
      kwgr:impactObservableProperty.deathIndirect ?deathIndirect ;
      kwgr:impactObservableProperty.injuryDirect ?injuryDirect ;
      kwgr:impactObservableProperty.injuryIndirect ?injuryIndirect
    ] .
}

