PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?hazardLabel ?detail ?time 
WHERE {
    { ?hazard rdfs:subClassOf kwg-ont:Hazard }
    UNION
    { ?hazard a kwg-ont:Hazard }

    OPTIONAL { ?hazard rdfs:label ?hazardLabel }
    OPTIONAL { 
        ?hazard (kwg-ont:hasGeometry|geo:hasDefaultGeometry) ?detail .
        FILTER(STRSTARTS(STRPNX(?detail, geo:wktLiteral), "Point"))
    }
    OPTIONAL { 
        ?hazard (kwg-ont:spatialRelation|sosa:phenomenonTime|kwg-ont:hasTemporalScope) ?time
    }
}

