PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardName ?placeName ?damageToCropsInDollars ?damageToInfrastructureInDollars 
       ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace 
       ?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace 
       ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
    :hasName ?hazardName ;
    kwgl-ont:hasImpacted ?place .

  ?place a kwgl-ont:Place ;
    :hasName ?placeName .

  FILTER NOT EXISTS { ?place :hasName "unspecified" }

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace }
}

